ResourceHandle hdr =
    graph.CreateTexture(
        "Scene HDR",
        TextureDesc{...});

PassHandle geometry =
    graph.AddPass({
        .Name = "Geometry",
        .Queue = Graphics,

        .Writes = {
            {
                hdr,
                ColorAttachmentWrite
            }
        }
    });

PassHandle bloom =
    graph.AddPass({
        .Name = "Bloom",
        .Queue = Compute,

        .Reads = {
            {
                hdr,
                SampledRead
            }
        },

        .Writes = {
            {
                bloomHalf,
                StorageWrite
            }
        }
    });

struct CompiledPass
{
    PassID Pass;

    QueueClass Queue;

    std::vector<Barrier>
        PreBarriers;

    std::vector<QueueWait>
        Waits;

    std::vector<QueueSignal>
        Signals;

    std::vector<PhysicalResourceBinding>
        Resources;

    ExecuteCallback Execute;
};

